const t = $('Sub').first().json;
const emb = $input.item.json.data[0].embedding;
const esc = (s) => String(s).replace(/'/g, "''");
// DWN-81: every value that reaches the SQL string is validated or escaped.
const ALLOWED_SOURCES = ['sessions','jobs','opportunities','forum','plain','gong','slack','nps','projects'];
// DWN-81 decision 10: the default is the user-voice sources only. Jobs,
// opportunities, Slack, NPS and projects are searched only when named.
let sourcesArr = "'{sessions,gong,forum,plain}'::text[]";
if (t.sources) {
  const parts = String(t.sources).split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
  const bad = parts.filter(p => !ALLOWED_SOURCES.includes(p));
  if (bad.length) throw new Error('Unknown source(s): ' + bad.join(', ') + '. Allowed: ' + ALLOWED_SOURCES.join(', '));
  if (parts.length) sourcesArr = "'{" + parts.join(',') + "}'::text[]";
}
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const DATE = /^\d{4}-\d{2}-\d{2}$/;
if (t.project_id && !UUID.test(String(t.project_id))) throw new Error('project_id must be a UUID');
if (t.date_from && !DATE.test(String(t.date_from))) throw new Error('date_from must be YYYY-MM-DD');
if (t.date_to && !DATE.test(String(t.date_to))) throw new Error('date_to must be YYYY-MM-DD');
const within = t.within ? "'" + esc(t.within) + "'::ltree" : 'null';
const approved = (t.approved === undefined || t.approved === null || t.approved === '') ? 'null' : (String(t.approved) === 'true' ? 'true' : 'false');
const projectId = t.project_id ? "'" + esc(t.project_id) + "'::uuid" : 'null';
const dateFrom = t.date_from ? "'" + esc(t.date_from) + "'::date" : 'null';
const dateTo = t.date_to ? "'" + esc(t.date_to) + "'::date" : 'null';
const k = Number(t.k) || 25;
const maxResults = Number(t.max_results) || 50;
const sql = "select * from public.search_all('[" + emb.join(',') + "]'::vector, '" + esc(t.query) + "', " + k + ", " + maxResults + ", " + sourcesArr + ", " + within + ", " + approved + ", " + projectId + ", " + dateFrom + ", " + dateTo + ")";
return { sql };

// DWN-81 decision 10: keep results small enough for 50 hits.
// - Omit the snippet when it repeats the start of the verbatim quote (most
//   session and Gong chunks).
// - Otherwise cut the snippet to SNIPPET_MAX characters.
// Full context is one call away through get_resource_context on the hit path.
const SNIPPET_MAX = 500;
const plain = (s) => String(s || '').replace(/<\/?b>/g, '').replace(/\s+/g, ' ').trim();
const shape = (r) => {
  const out = { ...r };
  const q = plain(r.quote).slice(0, 80);
  const sn = plain(r.snippet).slice(0, 80);
  if (q && sn && q === sn) {
    delete out.snippet;
  } else if (typeof r.snippet === 'string' && r.snippet.length > SNIPPET_MAX) {
    out.snippet = r.snippet.slice(0, SNIPPET_MAX) + '…';
  }
  return out;
};
const rows = $input.all().map(i => i.json).filter(r => r && r.source).map(shape);
const sources = [...new Set(rows.map(r => r.source))];

let emptyHint;
if (rows.length === 0) {
  const t = $('Sub').first().json;
  const widen = [];
  // approved is tri-state: omitted/null = ALL sessions, true = only approved,
  // false = only UNapproved. Never suggest approved:false — it narrows.
  if (t.approved === true || t.approved === 'true') {
    widen.push('drop the approved filter (omit it entirely — approved:false means ONLY unapproved sessions, a narrower set, not a wider one)');
  }
  if (t.within) widen.push("drop the within scope (you searched '" + t.within + "')");
  if (t.date_from || t.date_to) widen.push('drop or widen the date range');
  if (t.sources) widen.push('broaden sources (omit the sources parameter to search the default set: sessions, gong, forum, plain)');
  else widen.push('add opt-in sources if the question fits them (jobs, opportunities, slack, nps, projects)');
  widen.push('rephrase the query with different terms');
  emptyHint = 'No results. To widen, try in order: ' + widen.join('; ') + '. If none help, the corpus likely has nothing on this — say so rather than retrying with the same terms.';
}

return [{ json: {
  results: rows,
  meta: {
    count: rows.length,
    sources_searched: sources,
    citation_rule: 'Cite deep_link verbatim — never construct or paraphrase URLs.',
    snippet_note: 'The snippet is omitted when it repeats the quote, and cut to ' + SNIPPET_MAX + ' characters otherwise. Use get_resource_context on a hit path for the full context.',
    empty_hint: emptyHint
  }
} }];
